    // Not performance critical compared to the solve, but we still
    // apply a reasonable schedule: vectorize along the contiguous
    // dimension and parallelize rows of L.
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    if (vec_width > 1) {
        // x and b are 1D, contiguous in 'i'.
        init_x.compute_root().vectorize(i, vec_width);
        init_b.compute_root().vectorize(i, vec_width);

        // L(j, i): j is the fast-varying (contiguous) dimension.
        // Parallelize rows (i) and vectorize across columns (j).
        init_L.compute_root()
              .parallel(i)
              .vectorize(j, vec_width);
    } else {
        // Fallback: just compute at root with default scalar loops.
        init_x.compute_root();
        init_b.compute_root();
        init_L.compute_root();
    }
    // -----------------------------------------------------------

    init_x.realize(x);
    init_b.realize(b);
    init_L.realize(L);
}

int main(int argc, char *argv[]) {
    // problem size
    int n = N;

    // Buffers:
    // L: original is L[i][j]; we store as L(j, i) so that the first
    // dimension (j) is the fast-varying one.
    Halide::Buffer<num_t, 2> L(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> b(n);

    // ImageParams corresponding to L, x, b
    ImageParam L_param(type_of<num_t>(), 2, "L_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");
    ImageParam b_param(type_of<num_t>(), 1, "b_param");

    // Scalar Param for the current row index i
    Param<int> i_param("i_param");

    // initialize data
    init_array(n, L, x, b);

    // -----------------------------------------------------------------
    // Halide formulation of the inner computation:
    //
    // For a fixed i (driven from the host):
    //   x[i] = b[i];
    //   for (j = 0; j < i; j++)
    //       x[i] -= L[i][j] * x[j];
    //   x[i] = x[i] / L[i][i];
    //
    // As required by Halide, we avoid illegal self-references in Func
    // definitions. We:
    //   * Treat the already-computed x[0..i-1] as an ImageParam (x_param).
    //   * Drive the forward-substitution over i from the host.
    //   * Express the inner j-loop as a reduction over an RDom.
    //
    // We use a single Func "x_new" with a pure definition and two update
    // stages:
    //   x_new() = b[i]
    //   x_new() -= sum_j L[i,j] * x[j]
    //   x_new() /= L[i,i]
    //
    // The Func returns the scalar x[i] for the current i_param.
    // -----------------------------------------------------------------

    Func x_new("x_new");

    // RDom over j = 0 .. i_param-1
    RDom r(0, i_param, "r");

    // Pure definition: start from b[i]
    x_new() = b_param(i_param);

    // First update: subtract contributions L[i][j] * x[j]
    // Recall: L[i][j] is stored as L_param(j, i_param)
    x_new() -= L_param(r, i_param) * x_param(r);

    // Second update: divide by the diagonal entry L[i][i]
    x_new() /= L_param(i_param, i_param);

    // Bind ImageParams to our Buffers
    L_param.set(L);
    x_param.set(x);
    b_param.set(b);

    // ----------------- Schedule for x_new (inner kernel) -----------------
    // We keep the outer i-loop on the host strictly sequential to
    // respect the dependency x[i] <- x[0..i-1]. We optimize only the
    // reduction over j (RDom r), which has no loop-carried dependency
    // other than the scalar accumulator.
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    if (vec_width > 1) {
        // Split the reduction variable 'r' into [r_outer, r_inner] with
        // r_inner of size 'vec_width', and vectorize across r_inner.
        // This gives SIMD loads/stores over contiguous j for both
        // L_param(r, i_param) and x_param(r).
        RVar r_outer("r_outer"), r_inner("r_inner");
        x_new.update(0)        // update(0) is the "x_new() -=" stage
             .split(r, r_outer, r_inner, vec_width)
             .vectorize(r_inner);
    }
    // Note: we deliberately do *not* parallelize the reduction over r,
    // because x_new() is a scalar and there is no point introducing
    // extra synchronization or partial sums for this small kernel.
    // ---------------------------------------------------------------------

    // JIT-compile the pipeline once
    x_new.compile_jit(target);

    // -----------------------------------------------------------------
    // Run the triangular solve, timing only the kernel-like part:
    // -----------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // Reuse a 0-D buffer to avoid reallocating on every iteration.
    Halide::Buffer<num_t> x_scalar;

    for (int i = 0; i < n; i++) {
        // Set current row index
        i_param.set(i);

        // Realize scalar x_new() for this i into a 0-D buffer.
        // Using an existing Buffer avoids repeated allocations.
        x_new.realize(x_scalar);

        // Update x[i] on the host. This updated x is then visible
        // to the next iteration via x_param, which still refers to
        // the same underlying Buffer.
        x(i) = x_scalar();
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -----------------------------------------------------------------
    // Print results (similar style to example/gemm.cpp)
    // -----------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            std::cerr << x(i) << '\n';
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
