        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    // Realize into the provided buffers
    init_x.realize(x);
    init_b.realize(b);
    init_L.realize(L);
}

int main(int argc, char *argv[]) {
    // problem size
    int n = N;

    // Buffers:
    // L: original is L[i][j]; we store as L(j, i) so that the first
    // dimension (j) is the fast-varying one (row-major in j).
    Halide::Buffer<num_t, 2> L(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> b(n);

    // ImageParams corresponding to L, x, b
    ImageParam L_param(type_of<num_t>(), 2, "L_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");
    ImageParam b_param(type_of<num_t>(), 1, "b_param");

    // Scalar Param for the current row index i
    Param<int> i_param("i_param");

    // initialize data
    init_array(n, L, x, b);

    // Bind ImageParams to our Buffers (read-only views into L, x, b).
    // x is updated on the host between iterations, but from Halide's
    // point of view x_param is just an input buffer.
    L_param.set(L);
    x_param.set(x);
    b_param.set(b);

    // -----------------------------------------------------------------
    // Halide formulation of the inner computation:
    //
    // For a fixed i:
    //   x[i] = ( b[i] - sum_{j=0}^{i-1} L[i][j] * x[j] ) / L[i][i]
