    // Start from zero, accumulate L(i,j) * x(j)
    // Recall: logical L[i][j] is stored as L_param(j, i_param)
    dot() = cast<num_t>(Expr(0));
    dot() += L_param(r, i_param) * x_param(r);

    // Final scalar for x[i] = (b[i] - dot) / L[i][i]
    Func x_i("x_i");
    x_i() = (b_param(i_param) - dot()) / L_param(i_param, i_param);

    // -----------------------------------------------------------------
    // Schedule for the per-row dot product
    // -----------------------------------------------------------------
    //
    //  - i is driven sequentially from the host; we do *not* try to
    //    parallelize or reorder across i because of the triangular
    //    dependency x[0..i-1] -> x[i].
