    ImageParam x_param(type_of<num_t>(), 1, "x_param");
    ImageParam b_param(type_of<num_t>(), 1, "b_param");

    // Scalar Param for the current row index i
    Param<int> i_param("i_param");

    // initialize data
    init_array(n, L, x, b);

    // -----------------------------------------------------------------
    // Halide formulation of the inner computation:
    //
    // For a fixed i:
    //   x[i] = b[i];
    //   for (j = 0; j < i; j++)
    //       x[i] -= L[i][j] * x[j];
    //   x[i] = x[i] / L[i][i];
    //
    // We express the j-loop as a reduction over RDom, and drive the
    // i-loop from the host, updating x one element at a time.
    //
    // To allow better optimization of the reduction over j, we:
    //   * Compute the dot product s_i = sum_j L[i,j] * x[j] in Halide.
    //   * Perform the final scalar arithmetic (b[i] - s_i) / L[i,i]
    //     on the host. This keeps the Halide part purely as an
    //     associative sum and makes scheduling simpler.
    // -----------------------------------------------------------------

    Func dot("dot");  // dot() = sum_{j < i_param} L[i_param][j] * x[j]

    // RDom over j = 0 .. i_param-1
    RDom r(0, i_param, "r");

    // Start from zero and accumulate L[i][j] * x[j]
    dot() = cast<num_t>(Expr(0));
    // L[i][j] is stored as L_param(j, i_param)
    dot() += L_param(r, i_param) * x_param(r);

    // -----------------------------------------------------------------
    // Scheduling for the reduction over j:
    //
    //  - i (row index) is a scalar Param and is driven from the host
    //    in a strict increasing loop, so the triangular dependency
    //    x[0..i-1] -> x[i] is preserved.
    //  - For a fixed i, the reduction over j has no loop-carried
    //    dependence other than via the scalar accumulator, so we
    //    can safely unroll to expose instruction-level parallelism.
    //  - We avoid splitting or vectorizing the RDom directly to keep
    //    semantics simple and avoid any risk of double-counting;
    //    unrolling is always safe for a scalar reduction.
    // -----------------------------------------------------------------

    // Unroll a small factor of the inner reduction loop to increase ILP
    // and give the compiler more opportunities to fuse multiply-adds.
    dot.update().unroll(r, 4);

    // Compute dot at root. It is a scalar, so this simply ensures the
    // full reduction happens in a tight standalone loop.
    dot.compute_root();

    // Bind ImageParams to our Buffers; L is laid out as L(j, i) with j
    // fast-varying, so we get unit-stride accesses along the reduction.
    L_param.set(L);
    x_param.set(x);
    b_param.set(b);

    // JIT-compile the reduction once
    Target target = get_host_target();
    dot.compile_jit(target);

    // -----------------------------------------------------------------
    // Run the triangular solve, timing only the kernel-like part:
    // -----------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        // Set current row index
        i_param.set(i);

        // Compute the dot product s_i = sum_{j=0}^{i-1} L[i][j] * x[j]
        Halide::Buffer<num_t> dot_buf = dot.realize();

        num_t s_i = dot_buf();          // reduction result
        num_t bi  = b(i);               // b[i]
        num_t Lii = L(i, i);            // diagonal element L[i][i]

        // Finish the scalar operation on the host:
        //   x[i] = (b[i] - s_i) / L[i][i]
        x(i) = (bi - s_i) / Lii;
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -----------------------------------------------------------------
    // Print results (similar style to example/gemm.cpp)
    // -----------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            std::cerr << x(i) << '\n';
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
