#include <chrono>
#include <iomanip>
#include <iostream>

#include "Halide.h"

// include common definitions (e.g. N, DATA_TYPE)
#include "defines.hpp"

// include benchmark-specific definitions (same role as trisolv.h)
#include "trisolv.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/* Array initialization translated to Halide. */
static
void init_array(int n,
                Halide::Buffer<num_t, 2> L,  // logical L[i][j] stored as L(j, i)
                Halide::Buffer<num_t, 1> x,
                Halide::Buffer<num_t, 1> b) {
    Var i("i"), j("j");
    Func init_x("init_x"), init_b("init_b"), init_L("init_L");

    // x[i] = -999;
    init_x(i) = cast<num_t>(Expr(-999));

    // b[i] = i;
    init_b(i) = cast<num_t>(i);

    // L[i][j] = (DATA_TYPE) (i+n-j+1)*2/n for j <= i; 0 elsewhere (unused in kernel).
    // Remember: L is stored as L(j, i), with j (column) as the fast-varying dimension.
    Expr n_expr = cast<num_t>(Expr(n));
    Expr two    = cast<num_t>(Expr(2));

    init_L(j, i) = select(j <= i,
                          (cast<num_t>(i + n - j + 1) * two) / n_expr,
                          cast<num_t>(Expr(0)));

    // Realize initial data. The default schedule already walks j
    // (dimension 0) as the innermost loop, which matches the storage
    // layout of L, so we don't need additional scheduling here.
    init_x.realize(x);
    init_b.realize(b);
    init_L.realize(L);
}

int main(int argc, char *argv[]) {
    // problem size
    int n = N;

    // Buffers:
    // L: original is L[i][j]; we store as L(j, i) so that the first
    // dimension (j) is the fast-varying one.
    Halide::Buffer<num_t, 2> L(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> b(n);

    // ImageParams corresponding to L, x, b
    ImageParam L_param(type_of<num_t>(), 2, "L_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");
    ImageParam b_param(type_of<num_t>(), 1, "b_param");

    // Scalar Param for the current row index i
    Param<int> i_param("i_param");

    // initialize data
    init_array(n, L, x, b);

    // -----------------------------------------------------------------
    // Halide formulation of the inner computation:
    //
    // Mathematical kernel for fixed i:
    //
    //   x[i] = b[i];
    //   for (j = 0; j < i; j++)
    //       x[i] -= L[i][j] * x[j];
    //   x[i] = x[i] / L[i][i];
    //
    // We keep the i-loop on the host (strict forward dependency),
    // and express the inner j-loop in Halide as a reduction:
    //
    //   s(i) = sum_{j < i} L[i][j] * x[j]
    //   x[i] = (b[i] - s(i)) / L[i][i]
    //
    // L[i][j] is stored as L_param(j, i_param).
    // -----------------------------------------------------------------

    // Dot product over the already-solved part of row i:
    Func dot("dot");
    // Temporary for b[i] - dot:
    Func xi_val("xi_val");
    // Final scaled value x[i]:
    Func xi_div("xi_div");

    // Reduction domain over j = 0 .. i_param-1
    RDom r(0, i_param, "r");

    // Accumulate sum_{j < i} L[i][j] * x[j].
    // Start from zero to keep the reduction associative.
    dot() = cast<num_t>(Expr(0));
    // Recall: logical L[i][j] is stored as L_param(j, i_param).
    dot() += L_param(r, i_param) * x_param(r);

    // Compute b[i] - sum_j L[i][j] * x[j]
    xi_val() = b_param(i_param) - dot();

    // Divide by the diagonal entry L[i][i] (stored as L_param(i_param, i_param))
    xi_div() = xi_val() / L_param(i_param, i_param);

    // ---------------------------
    // Scheduling of the Halide kernel
    // ---------------------------
    // The outer i loop must remain on the host and strictly sequential,
    // due to the dependency x[i] -> x[i+1]. We therefore focus on
    // improving locality and ILP for the inner reduction over j.
    //
    // dot() is a 0-D Func (scalar) updated by a reduction on r. We:
    //   - keep it compute_root() so it becomes an explicit loop nest
    //     for each call to xi_div.realize()
    //   - unroll a small factor of r to increase ILP and reduce loop
    //     overhead inside the dot product
    //
    const int J_UNROLL = 4;  // small unroll factor for the inner reduction

    RVar r_outer("r_outer"), r_inner("r_inner");

    // Compute the reduction in a separate step (still once per call),
    // so we can schedule it explicitly.
    dot.compute_root();

    // Unroll the innermost part of the reduction over j (r).
    // Conceptually turns:
    //   for (int j = 0; j < i; j++)
    //       acc += L[i][j] * x[j];
    // into blocks of J_UNROLL scalar updates. This retains the same
    // arithmetic but improves instruction-level parallelism.
    dot.update()
        .split(r, r_outer, r_inner, J_UNROLL)
        .unroll(r_inner);

    // xi_val depends only on dot() and b[i], so we also compute it
    // explicitly at root per call. This keeps the pipeline simple and
    // makes sure the dot-product result is fully available before the
    // final division.
    xi_val.compute_root();
    // xi_div is the final scalar; leaving it inlined is fine.

    // Bind ImageParams to our Buffers (note: x is modified on the host
    // between iterations; the ImageParam keeps a pointer to the same
    // underlying Buffer, so each call sees the latest values).
    L_param.set(L);
    x_param.set(x);
    b_param.set(b);

    // JIT-compile the pipeline once.
    xi_div.compile_jit();

    // -----------------------------------------------------------------
    // Run the triangular solve, timing only the kernel-like part:
    // -----------------------------------------------------------------

    // Reuse a single 0-D buffer for the scalar result to avoid repeated
    // heap allocations on every iteration.
    Halide::Buffer<num_t> xi_buf;

    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        // Set current row index
        i_param.set(i);

        // Realize scalar xi_div() for this i into the reusable 0-D buffer
        xi_div.realize(xi_buf);

        // Update x[i] on the host
        x(i) = xi_buf();
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -----------------------------------------------------------------
    // Print results (similar style to example/gemm.cpp)
    // -----------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            std::cerr << x(i) << '\n';
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
